"""HTTP content negotiation (RFC 7231 Accept header), stdlib only."""

import re

_Q_RE = re.compile(r"^\s*q\s*=\s*([0-9.]+)\s*$", re.IGNORECASE)


def _parse_q(value):
    """Parse a q-value string, clamping to [0.0, 1.0] with 3 decimal places."""
    m = _Q_RE.match(value)
    if not m:
        return 1.0  # malformed q -> treat as absent parameter? No: invalid param
    try:
        q = float(m.group(1))
    except ValueError:
        return None
    q = max(0.0, min(1.0, q))
    # Truncate/round to 3 decimal places per RFC 7231
    return round(q, 3)


def parse_accept(header):
    """Parse an Accept header into a list of media ranges.

    Returns a list of dicts:
      {
        'type': str,        # lowercase type
        'subtype': str,     # lowercase subtype
        'q': float,         # quality value in [0.0, 1.0]
        'params': dict,     # non-q parameters (lowercased names)
      }
    Ordered as given in the header.
    """
    ranges = []
    if not header:
        return ranges
    for part in header.split(","):
        part = part.strip()
        if not part:
            continue
        pieces = part.split(";")
        media = pieces[0].strip().lower()
        if "/" not in media:
            continue  # malformed media range: skip
        type_, _, subtype = media.partition("/")
        type_ = type_.strip()
        subtype = subtype.strip()
        if not type_ or not subtype or type_ == "*" or subtype == "*":
            if type_ == "*" and subtype == "*":
                pass
            elif not type_ or not subtype:
                continue
        q = 1.0
        params = {}
        valid = True
        for raw_param in pieces[1:]:
            name, _, value = raw_param.partition("=")
            name = name.strip().lower()
            value = value.strip().strip('"')
            if name == "q":
                parsed = _parse_q(name + "=" + value) if False else None
                m = _Q_RE.match(raw_param.strip())
                if not m:
                    # malformed q; RFC says q is a decimal number.
                    # Treat garbage q as making the entry unusable -> q stays default?
                    # Safer: treat as malformed and clamp attempt fails -> use 1.0
                    try:
                        parsed_q = float(value)
                        q = round(max(0.0, min(1.0, parsed_q)), 3)
                    except ValueError:
                        q = 1.0
                else:
                    try:
                        parsed_q = float(m.group(1))
                        q = round(max(0.0, min(1.0, parsed_q)), 3)
                    except ValueError:
                        q = 1.0
            elif name:
                params[name] = value
        ranges.append(
            {"type": type_, "subtype": subtype, "q": q, "params": params}
        )
    return ranges


def _specificity(entry):
    """Specificity rank: 2 = type/subtype, 1 = type/*, 0 = */*."""
    if entry["type"] == "*":
        return 0
    if entry["subtype"] == "*":
        return 1
    return 2


def _matches(entry, mime_type):
    """Does a single media range entry match a concrete mime type?"""
    type_, _, subtype = mime_type.lower().partition("/")
    if entry["type"] != "*" and entry["type"] != type_:
        return False
    if entry["subtype"] != "*" and entry["subtype"] != subtype:
        return False
    # Range-specific parameters must match too (e.g. text/html;charset=utf-8)
    for name, value in entry["params"].items():
        # We don't track parameters on available types; ignore unless needed.
        pass
    return True


def best_match(header, available):
    """Pick the best matching media type from `available`.

    Ranking: highest q-value wins; ties broken by specificity
    (type/subtype > type/* > */*). Returns None if nothing is acceptable
    (no match, or all matches have q=0).
    """
    entries = [e for e in parse_accept(header) if e["q"] > 0.0]
    best = None
    best_key = None
    for candidate in available:
        for idx, entry in enumerate(entries):
            if _matches(entry, candidate):
                key = (entry["q"], _specificity(entry), -idx)
                if best_key is None or key > best_key:
                    best_key = key
                    best = candidate
                break  # first matching range for this candidate governs
    return best

